package dev.zomboid.lriso;
public final class Input {
 static boolean warned;
 static Object mc(){return R.call(R.type("net.minecraft.client.Minecraft"),"getInstance");}
 static boolean iso(){try{return R.yes(R.get(R.type("com.cleannrooster.dungeons_iso.mod.Mod"),"enabled"));}catch(IllegalStateException e){if(e.getCause() instanceof ClassNotFoundException)return false;throw e;}}
 public static boolean held(boolean original){try{Object mc=mc();if(original||!iso()||R.get(mc,"screen")!=null||R.get(mc,"player")==null||!R.yes(R.call(mc,"isWindowActive")))return original;Object mapping=R.get(R.type("me.xjqsh.lrtactical.client.input.AttackKeys"),"NORMAL_ATTACK"),key=R.call(mapping,"getKey");if(!R.call(key,"getType").toString().equals("MOUSE")||!R.call(mapping,"getKeyModifier").toString().equals("NONE"))return original;return ((Number)R.call(R.type("org.lwjgl.glfw.GLFW"),"glfwGetMouseButton",((Number)R.call(R.call(mc,"getWindow"),"getWindow")).longValue(),((Number)R.call(key,"getValue")).intValue())).intValue()==1;}catch(Throwable e){warn(e);return original;}}
 public static Object look(Object player){Object original=R.call(player,"getLookAngle");try{if(!iso()||player!=R.get(mc(),"player")||R.get(mc(),"screen")!=null)return original;Object hit=R.get(R.type("com.cleannrooster.dungeons_iso.mod.Mod"),"crosshairTarget");if(hit==null)return original;Object eye=R.call(player,"getEyePosition"),point=R.call(hit,"getLocation");double x=R.num(R.get(point,"x"))-R.num(R.get(eye,"x")),y=R.num(R.get(point,"y"))-R.num(R.get(eye,"y")),z=R.num(R.get(point,"z"))-R.num(R.get(eye,"z"));if(!R.call(hit,"getType").toString().equals("ENTITY"))y=0;double horizontal=Math.hypot(x,z),length=Math.sqrt(x*x+y*y+z*z);if(length<.1)return original;float yaw=(float)(Math.toDegrees(Math.atan2(z,x))-90),pitch=(float)-Math.toDegrees(Math.atan2(y,horizontal));R.call(player,"setYRot",yaw);R.call(player,"setYHeadRot",yaw);R.set(player,"yBodyRot",yaw);R.call(player,"setXRot",pitch);return R.make("net.minecraft.world.phys.Vec3",x/length,y/length,z/length);}catch(Throwable e){warn(e);return original;}}
 static void warn(Throwable e){if(!warned){warned=true;R.warn("isometric normal melee",e);}}
}
